import React, { Component } from "react";
import "./style.css";
import classnames from "classnames";
import PropTypes from "prop-types";
import { connect } from "react-redux";
import { loginUser } from "../actions/authActions";
import NavBar from "../components/NavBar";
import { withRouter, Link } from "react-router-dom";

class Login extends Component {
  constructor() {
    super();
    this.state = {
      email: "",
      password: "",
      errors: {}
    };
  }

  onChange = (e) => {
    this.setState({ [e.target.name]: e.target.value });
  };

  onSubmit = (e) => {
    e.preventDefault();
    const { email, password } = this.state;
    const newUser = { email, password };
    this.props.loginUser(newUser);
  };

  componentWillReceiveProps(nextProps) {
    if (nextProps.auth.isAuthenticated) {
      const { role, id } = nextProps.auth.users;
      if (role === "admin") {
        this.props.history.push("/dashboard");
      } else if (role === "student") {
        this.props.history.push(`/servicesforstudent/${id}`);
      } else if (role === "instructor") {
        this.props.history.push(`/servicesbyinstructor/${id}`);
      } else {
        this.props.history.push("/home-two");
      }
    }

    if (nextProps.errors) {
      this.setState({ errors: nextProps.errors });
    }
  }

  render() {
    const { email, password, errors } = this.state;
    const role = this.props.match.params.role || "student"; // fallback to student

    return (
      <div>
        <NavBar />
        <div className="auth-wrapper">
          <div className="auth-content container">
            <div className="card">
              <div className="row align-items-center">
                <div className="col-md-6">
                  <div className="card-body">
                    <div className="logoHead">
                      <img
                        src="/assets/img/onlinelearning.jpg"
                        alt="Logo"
                        height="60px"
                        width="60px"
                        className="sticky-logo img-fluid"
                      />
                      <h3>E-Learning</h3>
                    </div>
                    <h4 className="mb-3 f-w-400">Login into your account</h4>

                    <form noValidate onSubmit={this.onSubmit}>
                      <div className="input-group mb-2">
                        <div className="input-group-prepend">
                          <span className="input-group-text">
                            <i className="feather icon-mail" />
                          </span>
                        </div>
                        <input
                          name="email"
                          type="email"
                          className={classnames("form-control", {
                            "is-invalid": errors.email
                          })}
                          placeholder="Email address"
                          value={email}
                          onChange={this.onChange}
                        />
                        {errors.email && (
                          <div className="invalid-feedback">{errors.email}</div>
                        )}
                      </div>

                      <div className="input-group mb-3">
                        <div className="input-group-prepend">
                          <span className="input-group-text">
                            <i className="feather icon-lock" />
                          </span>
                        </div>
                        <input
                          name="password"
                          type="password"
                          className={classnames("form-control", {
                            "is-invalid": errors.password
                          })}
                          placeholder="Password"
                          value={password}
                          onChange={this.onChange}
                        />
                        {errors.password && (
                          <div className="invalid-feedback">
                            {errors.password}
                          </div>
                        )}
                      </div>

                      <div className="form-group text-left mt-2">
                        <div className="checkbox checkbox-fill d-inline">
                          <input
                            type="checkbox"
                            name="checkbox-fill-2"
                            id="checkbox-fill-2"
                          />
                          <label htmlFor="checkbox-fill-2" className="cr">
                            Save Credentials.
                          </label>
                        </div>
                      </div>

                      <button className="btn btn-primary shadow-2 mb-4" type="submit">
                        Login
                      </button>
                    </form>

                    <p className="mb-0 text-muted">
                      Don’t have an account?{" "}
                      <Link to={`/register/${role}`} className="f-w-400">
                        Signup
                      </Link>
                    </p>
                  </div>
                </div>

                <div className="col-md-6 d-none d-md-block">
                  <img
                    src="/assets/img/onlinelearning.jpg"
                    alt="Login Banner"
                    className="img-fluid"
                  />
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    );
  }
}

Login.propTypes = {
  loginUser: PropTypes.func.isRequired,
  auth: PropTypes.object.isRequired,
  errors: PropTypes.object.isRequired
};

const mapStateToProps = (state) => ({
  auth: state.auth,
  errors: state.errors
});

export default connect(mapStateToProps, { loginUser })(withRouter(Login));
